insert into public.places (slug, name, category, lat, lng, description, tip, status) values
  ('vysehrad-hradby', 'Hradby Vyšehradu', 'view', 50.0644, 14.4178, 'Procházka po hradbách s výhledem na Vltavu, Podolí a Hrad. Nejhezčí těsně před západem slunce.', 'Obejdi hradby celé dokola, nejlepší výhled je na jihozápadním cípu.', 'approved'),
  ('riegrovy-sady', 'Riegrovy sady – vyhlídka', 'view', 50.0803, 14.4417, 'Travnatý svah, ze kterého je vidět Hrad jako na dlani. Místní sem chodí na západ slunce.', 'Vezmi si deku a něco k pití.', 'approved'),
  ('letna-metronom', 'Metronom na Letné', 'view', 50.0946, 14.416, 'Obří metronom na místě bývalého Stalinova pomníku a výhled na pražské mosty.', 'V létě tu pod metronomem bývá bar a skejťáci.', 'approved'),
  ('vitkov', 'Vrch Vítkov', 'view', 50.0884, 14.4497, 'Obří jezdecká socha Jana Žižky a výhled na Žižkov i Karlín z jednoho místa.', 'Zpátky to vezmi dolů do Karlína na kávu.', 'approved'),
  ('divoka-sarka', 'Divoká Šárka', 'nature', 50.0997, 14.3236, 'Skalnaté údolí s potokem, které vůbec nevypadá jako Praha.', 'Vylez na skálu Dívčí skok, výhled stojí za to.', 'approved'),
  ('prokopske-udoli', 'Prokopské údolí – jezírko', 'nature', 50.0412, 14.39, 'Malé jezírko v bývalém lomu schované v zeleném údolí.', 'Pokračuj údolím dál, je tu klid i o víkendu.', 'approved'),
  ('grebovka', 'Grébovka', 'chill', 50.0689, 14.4443, 'Park s vinicí, altánem a umělou jeskyní uprostřed Vinohrad.', 'Ve viničním altánu si dej sklenku s výhledem na Nusle.', 'approved'),
  ('stromovka', 'Stromovka', 'nature', 50.106, 14.417, 'Největší pražský park s rybníky, starými stromy a spoustou místa.', 'Projdi až k Vltavě a přívozem nebo lávkou pokračuj do Troje.', 'approved'),
  ('ladronka', 'Ladronka', 'chill', 50.0775, 14.364, 'Dlouhý rovný park na Břevnově s usedlostí, kde se dá posedět.', 'Ideální na brusle nebo kolo.', 'approved'),
  ('letohradek-hvezda', 'Letohrádek Hvězda', 'culture', 50.0835, 14.3262, 'Renesanční letohrádek s půdorysem šesticípé hvězdy uprostřed obory.', 'Obora je skvělá na dlouhou procházku lesem.', 'approved'),
  ('petrin-rozhledna', 'Petřínská rozhledna', 'view', 50.0835, 14.3951, 'Malá sestra Eiffelovky na kopci nad Malou Stranou.', 'Dolů sejdi sady směrem na Újezd.', 'approved'),
  ('werichova-vila', 'Werichova vila na Kampě', 'culture', 50.0845, 14.4083, 'Vila u Čertovky, kde žil Jan Werich, dnes s výstavami a kavárnou.', 'Hned vedle je park Kampa a mlýnské kolo.', 'approved'),
  ('naplavka', 'Náplavka', 'chill', 50.0707, 14.4142, 'Nábřeží u Vltavy plné lidí, labutí a barů v kobkách.', 'V sobotu dopoledne tu bývají farmářské trhy.', 'approved'),
  ('zizkovska-vez', 'Žižkovská věž', 'view', 50.081, 14.4511, 'Televizní vysílač s lezoucími miminky od Davida Černého.', 'Pod věží je zahrádka a minigolf.', 'approved'),
  ('parukarka', 'Parukářka', 'view', 50.0853, 14.461, 'Žižkovský kopec s hospodou a jedním z nejlepších západů slunce ve městě.', 'Pivo z kelímku na trávě k tomu patří.', 'approved'),
  ('vrtbovska-zahrada', 'Vrtbovská zahrada', 'hidden', 50.0868, 14.4026, 'Barokní terasová zahrada schovaná za nenápadným průjezdem na Malé Straně.', 'Otevřeno jen v sezóně, vstup je placený.', 'approved'),
  ('vojanovy-sady', 'Vojanovy sady', 'hidden', 50.0893, 14.4085, 'Tichá zahrada za vysokou zdí, kde se procházejí pávi.', 'Vchod je z ulice U Lužického semináře.', 'approved'),
  ('frantiskanska-zahrada', 'Františkánská zahrada', 'hidden', 50.0826, 14.4238, 'Klidná zahrada pár kroků od Václavského náměstí, kterou spousta lidí mine.', 'Dá se sem dostat pasáží Světozor, vezmi si tam zmrzlinu.', 'approved'),
  ('novy-svet', 'Nový Svět', 'hidden', 50.0913, 14.3903, 'Ulička malých domků za Hradem, kde se zastavil čas a nejsou tu davy.', 'Projdi ji celou a pokračuj k Loretě.', 'approved'),
  ('trojsky-zamek', 'Trojský zámek', 'culture', 50.1165, 14.4127, 'Barokní zámek se zahradami a schodištěm plným soch.', 'Kousek nad ním jsou vinice sv. Kláry s výhledem.', 'approved'),
  ('botanicka-troja', 'Botanická zahrada v Troji', 'nature', 50.122, 14.414, 'Zahrady ve svahu nad Vltavou a tropický skleník Fata Morgana.', 'Japonská zahrada je nejhezčí na jaře a na podzim.', 'approved'),
  ('zricenina-baba', 'Zřícenina Baba', 'view', 50.1186, 14.389, 'Malá zřícenina na skále vysoko nad Vltavou s výhledem na Troju.', 'Cestou si prohlédni funkcionalistické vily osady Baba.', 'approved'),
  ('divci-hrady', 'Dívčí hrady', 'view', 50.0497, 14.4, 'Planina nad Smíchovem s širokým výhledem na celé město.', 'V ohradě se tu pasou koně Převalského.', 'approved'),
  ('strelecky-ostrov', 'Střelecký ostrov', 'chill', 50.081, 14.41, 'Ostrov pod mostem Legií, kde sedíš přímo u hladiny s výhledem na Národní divadlo.', 'Dojdi až na severní špičku ostrova.', 'approved'),
  ('kasarna-karlin', 'Kasárna Karlín', 'culture', 50.0915, 14.443, 'Bývalá kasárna proměněná v dvůr s barem, kinem a pískovištěm.', 'Program se mění, večer tu často něco hraje.', 'approved'),
  ('meetfactory', 'MeetFactory', 'culture', 50.0537, 14.4085, 'Umělecká továrna mezi kolejemi a magistrálou s červenými auty na fasádě.', 'Galerie bývají přístupné zdarma.', 'approved'),
  ('vystaviste', 'Výstaviště Holešovice', 'culture', 50.1065, 14.431, 'Secesní Průmyslový palác a areál, kde se pořád něco děje.', 'Odsud je to kousek do Stromovky.', 'approved'),
  ('kinskeho-zahrada', 'Kinského zahrada', 'nature', 50.079, 14.399, 'Park ve svahu Petřína s jezírky a dřevěným kostelíkem.', 'Najdi kostelík svatého Michala přivezený z Podkarpatské Rusi.', 'approved'),
  ('hostivarska-prehrada', 'Hostivařská přehrada', 'nature', 50.04, 14.538, 'Největší vodní plocha v Praze s lesoparkem okolo.', 'Okruh kolem přehrady je příjemná procházka na hodinu a půl.', 'approved'),
  ('kunraticky-les', 'Kunratický les', 'nature', 50.028, 14.475, 'Rozlehlý les na jihu Prahy s potokem a zříceninou Nového hradu.', 'Hledej zbytky hradu, kde zemřel Václav IV.', 'approved')
